"""Chronological 3-2 retrain: fit 2020-2022, select 2023, confirm 2024; isolated historical test 2025+. Not pristine OOS."""
from mindgo_api import *
import base64
import json
import math
import zlib
import numpy as np
import pandas as pd
COST_SCENARIO = 'neutral'
COST_SCENARIOS = {'optimistic': 0.002, 'neutral': 0.004, 'stress': 0.006, 'severe': 0.01}
_EMBEDDED_MODEL_B64 = ''
_EMBEDDED_STOP_MODEL_B64 = ''

def _load_model():
    if _EMBEDDED_MODEL_B64:
        raw = zlib.decompress(base64.b64decode(_EMBEDDED_MODEL_B64.encode('ascii')))
        return json.loads(raw.decode('utf-8'))
    raise ValueError('embedded model is empty')

def _tree_probability(model, values):
    raw = float(model['baseline'])
    for tree in model['fast_trees']:
        (feature, threshold, missing, left, right, leaf, value) = tree
        i = 0
        while not leaf[i]:
            x = values[feature[i]]
            go_left = missing[i] if np.isnan(x) else x <= threshold[i]
            i = left[i] if go_left else right[i]
        raw += value[i]
    if raw >= 0:
        z = math.exp(-raw)
        return 1.0 / (1.0 + z)
    z = math.exp(raw)
    return z / (1.0 + z)

def _batch_probabilities(model, rows):
    """Score the whole daily universe tree-by-tree instead of stock-by-stock."""
    x = np.asarray(rows, dtype=float)
    raw = np.full(len(x), float(model['baseline']), dtype=float)
    for (feature, threshold, missing, left, right, leaf, value) in model['fast_trees']:
        nodes = np.zeros(len(x), dtype=np.int32)
        active = ~leaf[nodes]
        while np.any(active):
            ri = np.flatnonzero(active)
            ni = nodes[ri]
            fi = feature[ni]
            xv = x[ri, fi]
            go_left = np.where(np.isnan(xv), missing[ni], xv <= threshold[ni])
            nodes[ri] = np.where(go_left, left[ni], right[ni])
            active[ri] = ~leaf[nodes[ri]]
        raw += value[nodes]
    out = np.empty_like(raw)
    positive = raw >= 0
    out[positive] = 1.0 / (1.0 + np.exp(-raw[positive]))
    z = np.exp(raw[~positive])
    out[~positive] = z / (1.0 + z)
    return out

def _last_features(df):
    if df is None or len(df) < 120:
        return None
    x = df.sort_index()
    c = x['close'].to_numpy(dtype=float)
    v = x['volume'].to_numpy(dtype=float)
    high = x['high'].to_numpy(dtype=float)
    low = x['low'].to_numpy(dtype=float)
    r = c[1:] / c[:-1] - 1.0
    vchg = v[1:] / v[:-1] - 1.0
    out = {}
    (out['ret5'], out['ret20'], out['ret60']) = (c[-1] / c[-6] - 1, c[-1] / c[-21] - 1, c[-1] / c[-61] - 1)
    out['range20'] = np.max(high[-20:]) / np.min(low[-20:]) - 1
    out['range60'] = np.max(high[-60:]) / np.min(low[-60:]) - 1
    out['dd20'] = c[-1] / np.max(c[-20:]) - 1
    (out['vol20'], out['vol60']) = (np.std(r[-20:], ddof=1), np.std(r[-60:], ddof=1))
    mean_v20 = np.mean(v[-20:])
    out['volume_ratio'] = np.mean(v[-5:]) / mean_v20
    out['volume_cv'] = np.std(v[-20:], ddof=1) / mean_v20
    out['up_volume_share'] = np.sum(v[-20:][r[-20:] > 0]) / np.sum(v[-20:])
    out['pv_corr'] = np.corrcoef(r[-20:], vchg[-20:])[0, 1]
    (low60, high60) = (np.min(c[-60:]), np.max(c[-60:]))
    out['close_pos60'] = (c[-1] - low60) / (high60 - low60) if high60 != low60 else np.nan
    out['turn20'] = np.mean(x['turnover_rate'].to_numpy(dtype=float)[-20:])
    amount20 = np.mean(x['turnover'].to_numpy(dtype=float)[-20:])
    out['amount20'] = np.log1p(amount20)
    out['breakout_gap'] = c[-1] / np.max(c[-61:-1]) - 1
    out['rise_from_low60'] = c[-1] / low60 - 1
    out['volume_spike'] = v[-1] / mean_v20
    if out['ret5'] > 0.12 or out['ret20'] > 0.2 or out['rise_from_low60'] > 0.3 or (out['volume_spike'] > 5) or (high[-1] == low[-1]) or (float(x['quote_rate'].iloc[-1]) >= 19.5) or (amount20 < 50000000) or bool(x['is_st'].iloc[-1]):
        return None
    values = [float(out[name]) for name in g.model['features']]
    if not np.all(np.isfinite(values)):
        return None
    return values

def _load_stop_model():
    raw = zlib.decompress(base64.b64decode(_EMBEDDED_STOP_MODEL_B64.encode('ascii')))
    model = json.loads(raw.decode('utf-8'))
    model['fast_trees'] = [(np.asarray([n['f'] for n in tree], dtype=np.int16), np.asarray([n['t'] for n in tree]), np.asarray([n['m'] for n in tree], dtype=bool), np.asarray([n['l'] for n in tree], dtype=np.int16), np.asarray([n['r'] for n in tree], dtype=np.int16), np.asarray([n['leaf'] for n in tree], dtype=bool), np.asarray([n['v'] for n in tree])) for tree in model['trees']]
    return model
STRATEGY_VERSION = '科创3-2：2022截止重训测试版'
SIGNAL_THRESHOLD = 0.63

def init(context):
    g.model = _load_model()
    g.model['threshold'] = SIGNAL_THRESHOLD
    g.model['fast_trees'] = [(np.asarray([n['f'] for n in t], dtype=np.int16), np.asarray([n['t'] for n in t]), np.asarray([n['m'] for n in t], dtype=bool), np.asarray([n['l'] for n in t], dtype=np.int16), np.asarray([n['r'] for n in t], dtype=np.int16), np.asarray([n['leaf'] for n in t], dtype=bool), np.asarray([n['v'] for n in t])) for t in g.model['trees']]
    g.stop_model = _load_stop_model()
    g.pending = []
    g.position_state = {}
    g.adjustment_anchor = {}
    g.order_intent = {}
    g.order_locks = {}
    g.early_events = {}
    g.submitting = False
    g.seen_fills = {}
    g.exit_prices = {}
    g.daily_buy_value = 0.0
    g.daily_sell_value = 0.0
    g.buy_done_date = None
    set_benchmark('000688.SH')
    set_slippage(PriceSlippage(COST_SCENARIOS[COST_SCENARIO]))
    set_commission(PerShare(type='stock', cost=0.0003, min_trade_cost=5.0))
    set_volume_limit(daily=0.25, minute=0.5)
    log.info('%s DAILY threshold=%.2f; historical results are development evidence' % (STRATEGY_VERSION, SIGNAL_THRESHOLD))

def _past(frame, today):
    if frame is None or frame.empty:
        return None
    x = frame.copy()
    x.index = pd.to_datetime(x.index)
    return x[x.index.normalize() < pd.Timestamp(today)].sort_index()

def _adjust_entry(symbol, frame):
    old = g.adjustment_anchor.get(symbol)
    state = g.position_state.get(symbol)
    if old is not None and state is not None:
        rows = frame[frame.index.normalize() == pd.Timestamp(old['date'])]
        if rows.empty:
            log.warn('ACTION_ANCHOR_MISSING %s: exit signal skipped' % symbol)
            return False
        factor = float(rows['close'].iloc[-1]) / old['close']
        if not np.isfinite(factor) or factor <= 0:
            raise ValueError('Invalid adjustment factor for ' + symbol)
        state['entry'] *= factor
        if abs(factor - 1.0) > 1e-08:
            log.info('CORPORATE_ACTION %s factor=%.10f entry=%.6f' % (symbol, factor, state['entry']))
    g.adjustment_anchor[symbol] = {'date': str(frame.index[-1].date()), 'close': float(frame['close'].iloc[-1])}
    return True

def before_trading(context):
    today = get_datetime().date()
    g.order_locks = {}
    g.order_intent = {}
    g.early_events = {}
    g.seen_fills = {}
    g.daily_buy_value = g.daily_sell_value = 0.0
    g.pending = []
    g.exit_prices = {}
    g.buy_done_date = None
    benchmark = history(['000001.SH'], ['close'], 5, '1d', False, 'pre', True, False)
    b = _past(benchmark.get('000001.SH'), today)
    if b is None or b.empty:
        raise ValueError('Missing previous trading date; no frozen-universe fallback')
    g.signal_date = b.index[-1].date()
    securities = get_all_securities('stock', g.signal_date.strftime('%Y%m%d'))
    universe = set((s for s in securities.index if s.startswith('688') and s.endswith('.SH')))
    if not universe:
        raise ValueError('Historical STAR universe unavailable')
    symbols = sorted(universe | set(context.portfolio.positions.keys()))
    fields = ['open', 'high', 'low', 'close', 'volume', 'turnover', 'turnover_rate', 'quote_rate', 'is_st']
    rows = []
    for begin in range(0, len(symbols), 300):
        batch = symbols[begin:begin + 300]
        data = history(batch, fields, 121, '1d', False, 'pre', True, False)
        for symbol in batch:
            frame = _past(data.get(symbol), today)
            if frame is None or frame.empty:
                log.warn('MISSING_HISTORY %s holding retained' % symbol)
                continue
            adjusted = _adjust_entry(symbol, frame)
            if frame.index[-1].date() != g.signal_date:
                continue
            if adjusted:
                g.exit_prices[symbol] = float(frame['close'].iloc[-1])
            if symbol not in universe:
                continue
            values = _last_features(frame)
            if values is not None:
                rows.append((symbol, values))
    if rows:
        values = [r[1] for r in rows]
        p = _batch_probabilities(g.model, values)
        stop = _batch_probabilities(g.stop_model, values)
        scores = [(rows[i][0], float(p[i]), float(p[i] - 0.22 * stop[i])) for i in range(len(rows)) if p[i] >= SIGNAL_THRESHOLD and stop[i] <= 0.35]
        scores.sort(key=lambda r: (-r[2], r[0]))
        g.pending = [(r[0], r[1]) for r in scores[:g.model['top_per_day']]]
    log.info('SIGNAL_AUDIT asof=%s callback=%s universe=%d scored=%d pending=%s' % (str(g.signal_date), str(get_datetime()), len(universe), len(rows), str(g.pending)))

def _place(symbol, action, target):
    if symbol in g.order_locks:
        return None
    g.order_locks[symbol] = 'SUBMITTING'
    g.submitting = True
    try:
        oid = order_target_percent(symbol, 0.1) if action == 'BUY' else order_target(symbol, int(target))
    except Exception:
        g.order_locks.pop(symbol, None)
        raise
    finally:
        g.submitting = False
    if oid is None:
        g.order_locks.pop(symbol, None)
        return None
    g.order_intent[oid] = {'symbol': symbol, 'action': action}
    g.order_locks[symbol] = oid
    for event in g.early_events.pop(oid, []):
        _process_order(event)
    return oid

def on_order(context, odr):
    event = {'id': odr.order_id, 'status': str(odr.status).upper(), 'filled': float(odr.filled_amount), 'price': float(odr.avg_price)}
    if event['id'] not in g.order_intent:
        if g.submitting:
            g.early_events.setdefault(event['id'], []).append(event)
        return
    _process_order(event)

def _process_order(event):
    oid = event['id']
    intent = g.order_intent.get(oid)
    if intent is None:
        return
    (symbol, action) = (intent['symbol'], intent['action'])
    (qty, price) = (event['filled'], event['price'])
    (old_qty, old_value) = g.seen_fills.get(oid, (0.0, 0.0))
    if qty >= old_qty and qty > 0 and np.isfinite(price) and (price > 0):
        value = qty * price
        delta = value - old_value
        if action == 'BUY':
            g.daily_buy_value += delta
            g.position_state[symbol] = {'entry': price, 'half': False, 'entry_date': get_datetime().date()}
        else:
            g.daily_sell_value += delta
            if action == 'TPHALF' and qty > old_qty and (symbol in g.position_state):
                g.position_state[symbol]['half'] = True
        g.seen_fills[oid] = (qty, value)
    status = event['status']
    terminal = 'REJECT' in status or 'CANCEL' in status or ('FILLED' in status and 'PART' not in status)
    log.info('ORDER_AUDIT id=%s symbol=%s action=%s status=%s qty=%s avg=%s time=%s' % (str(oid), symbol, action, status, str(qty), str(price), str(get_datetime())))
    if terminal:
        g.order_intent.pop(oid, None)
        g.order_locks.pop(symbol, None)

def _exit_action(price, state, amount, today, position_days):
    entry = state['entry']
    if entry <= 0 or not np.isfinite(price):
        return None
    start = state['entry_date']
    age = (today - start).days if start is not None else int(position_days)
    gain = price / entry - 1
    if gain <= -0.07:
        return ('STOP', 0)
    if gain >= 0.34:
        return ('TPALL', 0)
    if age >= 60:
        return ('TIME60', 0)
    if age >= 30 and gain < 0.1:
        return ('TIME30', 0)
    target = int(amount / 2)
    if gain >= 0.24 and (not state['half']) and (target >= 200) and (int(amount) - target >= 200):
        return ('TPHALF', target)
    return None

def _open_tradable(symbol, bars):
    try:
        bar = bars[symbol]
    except KeyError:
        return (False, False, False, np.nan)
    price = float(bar.open)
    valid = not bool(bar.is_paused) and np.isfinite(price) and (price > 0)
    return (valid, price >= float(bar.high_limit) - 0.001, price <= float(bar.low_limit) + 0.001, price)

def handle_bar(context, bar_dict):
    today = get_datetime().date()
    if g.buy_done_date == today:
        return
    g.buy_done_date = today
    positions = context.portfolio.positions
    for symbol in list(g.position_state):
        if symbol not in positions or float(positions[symbol].amount) <= 0:
            g.position_state.pop(symbol, None)
    slots = max(0, g.model['max_positions'] - sum((float(p.amount) > 0 for p in positions.values())))
    for (symbol, probability) in g.pending:
        if slots <= 0:
            break
        if symbol in positions and float(positions[symbol].amount) > 0:
            continue
        (valid, up, _, price) = _open_tradable(symbol, bar_dict)
        if not valid or up or float(context.portfolio.stock_account.available_cash) < price * 200 * 1.005:
            continue
        if _place(symbol, 'BUY', None) is not None:
            slots -= 1
    for symbol in list(positions):
        pos = positions[symbol]
        if float(pos.amount) <= 0 or int(pos.position_days) <= 0:
            continue
        if symbol not in g.position_state:
            log.warn('RECOVERED_POSITION %s: entry date unknown; using platform holding days' % symbol)
            g.position_state[symbol] = {'entry': float(pos.cost_basis), 'half': False, 'entry_date': None}
        state = g.position_state[symbol]
        if state['entry_date'] == today or symbol not in g.exit_prices:
            continue
        (valid, _, down, price) = _open_tradable(symbol, bar_dict)
        if not valid or down:
            continue
        decision = _exit_action(g.exit_prices[symbol], state, pos.amount, today, pos.position_days)
        if decision is not None:
            log.info('EXIT_SIGNAL %s asof=%s signal_price=%.6f entry=%.6f open=%.6f action=%s' % (symbol, str(g.signal_date), g.exit_prices[symbol], state['entry'], price, decision[0]))
            _place(symbol, decision[0], decision[1])

def after_trading(context):
    total = float(context.portfolio.stock_account.total_value)
    gross = g.daily_buy_value + g.daily_sell_value
    log.info('EXECUTION_AUDIT buy=%.2f sell=%.2f gross=%.2f nav=%.2f turnover=%.6f open_intents=%d' % (g.daily_buy_value, g.daily_sell_value, gross, total, gross / total if total > 0 else np.nan, len(g.order_intent)))
